// Verify HTTP status code
pm.test("Status code is 200", function () {
    pm.response.to.have.status(200);
});

// Parse response
const users = pm.response.json();

// Verify response is a non-empty array
pm.test("Response is a non-empty array", function () {
    pm.expect(users).to.be.an("array");
    pm.expect(users.length).to.be.greaterThan(0);
});

// Verify that the response contains user information
pm.test("Response contains user information", function () {
    pm.expect(users[0]).to.have.property("id");
    pm.expect(users[0]).to.have.property("name");
    pm.expect(users[0]).to.have.property("email");
});

// Verify every user has id, name and email
pm.test("Each user has id, name and email", function () {
    users.forEach(function (user) {
        pm.expect(user).to.have.property("id");
        pm.expect(user).to.have.property("name");
        pm.expect(user).to.have.property("email");

        pm.expect(user.id).to.not.be.null;
        pm.expect(user.name).to.not.be.empty;
        pm.expect(user.email).to.not.be.empty;
    });
});

// Save the first user's ID for use in later requests
pm.collectionVariables.set("userId", users[0].id);

// Verify HTTP status code
pm.test("Status code is 200", function () {
    pm.response.to.have.status(200);
});

// Parse response
const user = pm.response.json();

// Verify the response contains the requested user
pm.test("Response contains user information", function () {
    pm.expect(user).to.be.an("object");
    pm.expect(user).to.have.property("id");
    pm.expect(user).to.have.property("name");
    pm.expect(user).to.have.property("email");
});

// Verify returned ID matches the saved ID
pm.test("Returned ID matches saved user ID", function () {
    pm.expect(user.id).to.eql(
        Number(pm.collectionVariables.get("userId"))
    );
});

// Verify required fields are not empty
pm.test("User name and email are not empty", function () {
    pm.expect(user.name).to.not.be.empty;
    pm.expect(user.email).to.not.be.empty;
});

pm.collectionVariables.set("userPhone", user.phone);

// Generate dynamic update data
const timestamp = Date.now();

pm.variables.set("updatedName", `Updated User ${timestamp}`);
pm.variables.set("updatedEmail", `updated.${timestamp}@example.com`);
pm.variables.set("updatedCompany", `Updated Company ${timestamp}`);

// Verify HTTP status code
pm.test("Status code is 200", function () {
    pm.response.to.have.status(200);
});

// Parse response
const response = pm.response.json();

// Verify returned ID matches the saved ID
pm.test("Returned ID matches saved user ID", function () {
    pm.expect(response.id).to.eql(
        Number(pm.collectionVariables.get("userId"))
    );
});

// Verify phone is not empty
pm.test("Phone is not empty", function () {
    pm.expect(response.phone).to.not.be.empty;
});

// Verify returned name matches the updated name
pm.test("Returned name matches updated name", function () {
    pm.expect(response.name).to.eql(
        pm.variables.get("updatedName")
    );
});

// Verify returned email matches the updated email
pm.test("Returned email matches updated email", function () {
    pm.expect(response.email).to.eql(
        pm.variables.get("updatedEmail")
    );
});

// Verify returned company name matches the updated company
pm.test("Returned company name matches updated company", function () {
    pm.expect(response.company.name).to.eql(
        pm.variables.get("updatedCompany")
    );
});
